export interface ConnectorConfig {
  hubspotAccessToken: string
  fetch?: typeof fetch
}

export interface StripeCheckoutSessionPayload {
  id: string
  object: string
  customer: string | { email?: string }
  customer_email?: string
  payment_status: string
  status: string
  amount_total: number
  currency: string
  mode: string
  client_reference_id?: string
  metadata?: Record<string, unknown>
}

export interface HubSpotContactResponse {
  vid: number
  isNew: boolean
  email: string
}

export interface HandleResult {
  hubspotContactId: number
  isNewContact: boolean
  email: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? (globalThis.fetch ?? fetch)
}

function extractCustomerEmail(payload: StripeCheckoutSessionPayload): string {
  if (payload.customer_email) {
    return payload.customer_email
  }
  if (typeof payload.customer === 'object' && payload.customer !== null && 'email' in payload.customer) {
    const email = (payload.customer as { email?: string }).email
    if (email) return email
  }
  throw new Error('Customer email not found in payload: missing customer_email and customer.email')
}

export async function handle(
  payload: StripeCheckoutSessionPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  if (!payload.id) {
    throw new Error('Missing required field: id (Stripe session ID)')
  }
  if (!config.hubspotAccessToken) {
    throw new Error('Missing required config: hubspotAccessToken')
  }

  const email = extractCustomerEmail(payload)
  const fetchImpl = getFetch(config)

  const url = `https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/${encodeURIComponent(email)}`
  const body = {
    properties: [
      { property: 'email', value: email }
    ]
  }

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.hubspotAccessToken}`,
      'Content-Type': 'application/json',
      'Idempotency-Key': payload.id
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    throw new Error(`HubSpot API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  }

  }

  const data = await response.json() as HubSpotContactResponse

  return {
    hubspotContactId: data.vid,
    isNewContact: data.isNew,
    email: data.email
  }
}

